 SELECT CASE WHEN NEW.source='purchase' AND ((SELECT COUNT(*) FROM lp_catalog_mapping_components WHERE mapping_id=NEW.id)!=1 OR NOT EXISTS(SELECT 1 FROM lp_suppliers WHERE id=NEW.supplier_id)) THEN RAISE(ABORT,'CATALOG_INVALID_SUPPLIER') END;
